const LYRIC_BANK=[{"id":"jp-000","lang":"jp","theme":"衝動","title":"フェンスの外","v1":["通学路の先は工事中","昨日と同じ札が揺れる"],"chorus":["回り道なら俺が決める","矢印よりも足を信じろ","誰かの近道をなぞるより","俺の迷いを連れてゆく"],"v2":["靴にくっついた砂利を蹴る","知らない路地から風が来た"],"bridge":["行き止まりでも構わない","自分で見つけた壁ならいい"],"outro":"地図の白いところへ","hook":["No borrowed sign, no borrowed road","A moving heart can take the load"]},{"id":"jp-001","lang":"jp","theme":"衝動","title":"赤信号の先","v1":["交差点でみんなが止まる","待つ理由まで同じ顔だ"],"chorus":["走りたいのは道じゃない","胸の信号を変えたいんだ","速さを競うためじゃない","止まった胸を動かすためだ"],"v2":["青になっても立ったままで","俺は別の方角を見た"],"bridge":["急ぐことなら誰でもできる","行く先だけは譲れない"],"outro":"今度の角を左へ","hook":["The street turns green, my thoughts turn wide","I choose the turn I keep inside"]},{"id":"jp-002","lang":"jp","theme":"衝動","title":"制服の裏側","v1":["ボタンの裏に文字を書いた","誰にも見えない俺の名前"],"chorus":["この襟だけで呼ばないでくれ","内側には別の熱がある","揃えた列には見えなくても","はみ出す鼓動は隠せない"],"v2":["鏡の前で袖をまくる","昨日より少し腕が出た"],"bridge":["決まりを全部破らなくても","俺を隠す布はいらない"],"outro":"窓を開けて着替えよう","hook":["No label knows the pulse in here","It never learned the sound I hear"]},{"id":"jp-003","lang":"jp","theme":"衝動","title":"無記名の切符","v1":["行き先のない切符を描く","財布の底で折れていた"],"chorus":["まだ乗れなくても捨てるなよ","改札の外に朝はある","小さな紙でも帆になるさ","まだ知らない風を受け止めろ"],"v2":["ホームの音が遠く聞こえる","今日は駅まで歩いてみる"],"bridge":["乗り遅れたとは言わせない","発車の時刻を決めていない"],"outro":"白い欄に街を書こう","hook":["A little paper, still unwritten","Can hold a wind I've never ridden"]},{"id":"jp-004","lang":"jp","theme":"衝動","title":"朝までの落書き","v1":["消された壁に跡が残る","灰色の上に灰色の線"],"chorus":["塗りつぶせないものがある","言いかけた声がここにある","薄い跡から声が出る","消した昨日より強い声だ"],"v2":["言葉の代わりに指を走らせ","曇った窓へ丸を描いた"],"bridge":["明日になれば消えてもいい","書いた手まで消えはしない"],"outro":"袖口だけが汚れてる","hook":["A fading line, a stubborn trace","Somebody lived inside this space"]},{"id":"jp-005","lang":"jp","theme":"衝動","title":"靴紐の宣言","v1":["玄関に並ぶきれいな靴","俺の一足だけ泥だらけ"],"chorus":["行儀のいい道ばかりじゃ","見たい景色に届かない","大きな夢を語る前に","小さな石を踏んでみろ"],"v2":["ほどけた紐を結び直す","何度もしゃがんでまた立った"],"bridge":["遠くへ行くと決めたのなら","まずこの足を連れてゆけ"],"outro":"結び目をきつくして","hook":["Tie it tight and take it slow","These feet have somewhere else to go"]},{"id":"jp-006","lang":"jp","theme":"衝動","title":"退屈を返せ","v1":["時間割の隅を黒くする","紙の向こうで空が光る"],"chorus":["借りた一日を返すから","俺の一日を渡してくれ","使い残した熱がある","チャイムの外まで持ってゆく"],"v2":["鐘の音より早く立った","行くあてはまだ決めていない"],"bridge":["言われた通りの未来より","自分の間違いを選びたい"],"outro":"扉の重さを覚えた","hook":["The bell can stop the clock at school","It cannot make the heart a rule"]},{"id":"jp-007","lang":"jp","theme":"衝動","title":"放課後の穴","v1":["校庭の隅の抜け道は","大人の地図に載っていない"],"chorus":["狭い隙間を抜けてゆけ","胸まで小さくするなよ","広い門でも狭いなら","俺の大きさで抜けてゆけ"],"v2":["鞄が枝に引っかかった","笑って外してまた進む"],"bridge":["立派な門がなくたって","俺達には入口がある"],"outro":"葉っぱをつけて帰ろう","hook":["The narrow gap, the open air","A different world is waiting there"]},{"id":"jp-008","lang":"jp","theme":"衝動","title":"ポケットの雷","v1":["天気予報は晴れだと言う","胸の中だけ雲が重い"],"chorus":["鳴らせよ小さな雷を","聞こえる場所から変えてゆけ","晴れた顔して歩いてても","腹の底では雨が降る"],"v2":["溜めた言葉を紙に書けば","思ったよりも短かった"],"bridge":["大きな声じゃなくていい","飲み込む前に外へ出せ"],"outro":"最初の一行が光る","hook":["A little storm beneath my coat","Can find a sky inside a note"]},{"id":"jp-009","lang":"jp","theme":"衝動","title":"正解の裏口","v1":["答え合わせの赤い丸","嬉しいはずが息が詰まる"],"chorus":["正しいだけじゃ足りないよ","俺は問いから作りたい","間違えたって名前をつけろ","誰の答えでもないように"],"v2":["余白に別の道を描く","誰も採点してくれない"],"bridge":["間違いだって歩けるなら","そこにも俺の足跡だ"],"outro":"丸の外側が広がる","hook":["A crooked question starts to grow","Beyond the things I ought to know"]},{"id":"jp-010","lang":"jp","theme":"衝動","title":"屋上の風向き","v1":["鍵の開いた屋上で","街の音だけ聞いていた"],"chorus":["風に名前をつけるなよ","俺もまだ形を変える","下りる階段は逃げはしない","遠い景色を先にくれ"],"v2":["下から誰かが呼んでいる","返事をしても降りなかった"],"bridge":["逃げるためじゃなく上がった","遠くを見る目が欲しかった"],"outro":"もう少しここにいよう","hook":["I came up here to see some sky","Not just to let the street pass by"]},{"id":"jp-011","lang":"jp","theme":"衝動","title":"消灯後の赤","v1":["消灯の声が廊下を渡る","布団の中で目だけ冴える"],"chorus":["眠ったふりはもうやめだ","真っ暗なほど火が見える","寝返りだけでは消えやしない","胸の小さな赤い点"],"v2":["机の下へノートを隠す","続きを頭で繰り返した"],"bridge":["誰にも見せない始まりを","誰にも渡さず育てよう"],"outro":"朝まで赤を守ってる","hook":["The room goes dark, the spark stays red","I keep a waking world instead"]},{"id":"jp-012","lang":"jp","theme":"恋の始まり","title":"返さないでB面","v1":["貸したレコードの角が丸い","君の部屋には似合わない色"],"chorus":["返さないでまだ返さないで","会うための理由がなくなるから","感想よりも声が聴きたい","擦れたジャケット言い訳にして"],"v2":["傷がついたと電話が来た","確かめに行くとすぐ答えた"],"bridge":["新品ならまた買えるけど","君が聴いた音は買えない"],"outro":"針は三曲目を回る","hook":["The needle waits, the music stays","I need another little phrase"]},{"id":"jp-013","lang":"jp","theme":"恋の始まり","title":"ひと駅ぶん","v1":["隣に君が座っただけで","いつもの駅が近すぎる"],"chorus":["もうひと駅だけ遠くなれ","言葉を探す時間をくれ","降りるつもりの顔のままで","君の続きを待っている"],"v2":["窓の名前を読み上げながら","降りる支度を遅らせた"],"bridge":["遠回りでもいいですか","今ならそれだけ言えそうだ"],"outro":"君が鞄を膝に戻す","hook":["Another stop, another mile","A little courage takes a while"]},{"id":"jp-014","lang":"jp","theme":"恋の始まり","title":"貸した傘の天気","v1":["傘を返すと約束した日","朝から空は青すぎた"],"chorus":["雨でもないのに会いたくて","天気の話を長くする","晴れた言い訳ほどけたら","雨より素直な俺で行く"],"v2":["降りそうだねと嘘をつけば","君は窓から空を見ている"],"bridge":["理由が晴れてなくなっても","会いたい気持ちは残るんだ"],"outro":"傘を二人で畳んだ","hook":["The sun took all my reasons away","And left the thing I meant to say"]},{"id":"jp-015","lang":"jp","theme":"恋の始まり","title":"角砂糖ひとつ","v1":["君のカップへ手を伸ばし","砂糖の数を聞いてみた"],"chorus":["甘くしすぎず苦くもなく","君の好みを覚えたい","溶けた数だけ近くなる","甘さじゃ測れない君へ"],"v2":["自分のカップは冷めていた","それにも気づかず話してた"],"bridge":["好きなものからひとつずつ","知らない君を減らしてゆく"],"outro":"次は聞かずに渡せるね","hook":["A little sugar, not too sweet","Another thing I learn to keep"]},{"id":"jp-016","lang":"jp","theme":"恋の始まり","title":"書きかけの宛名","v1":["封筒の隅に君の名前","そこから先が書けなくなる"],"chorus":["たった四文字が重すぎて","便箋ばかり軽くなる","きれいな文字にはできなくても","震えたところも読んでほしい"],"v2":["上手な言葉を消したあと","今日見た花を描いてみた"],"bridge":["伝えることがひとつなら","飾らない字でいいのかな"],"outro":"切手を貼ってしまおうか","hook":["A folded page, a shaky hand","Can say the things I never planned"]},{"id":"jp-017","lang":"jp","theme":"恋の始まり","title":"約束のない日曜","v1":["何も予定のない日曜","君の予定が気になった"],"chorus":["暇だと言えば会えるかな","忙しいふりをほどいてみる","空いた時間を埋めたいんじゃない","君のいる日を作りたい"],"v2":["用もないのに店を覗く","君に似た声で振り返る"],"bridge":["偶然ばかり待つよりも","明日は自分で誘ってみよう"],"outro":"小銭を握って電話する","hook":["A day with nothing written through","Has room to write a little you"]},{"id":"jp-018","lang":"jp","theme":"恋の始まり","title":"洗いたてのシャツ","v1":["いつも着ない色を選んだ","鏡の前で肩が上がる"],"chorus":["似合うかどうかは後でいい","君に気づいてほしいだけ","似合わぬ色でも君が笑えば","次に着る理由になる"],"v2":["待ち合わせより早く着いた","襟を触る手が止まらない"],"bridge":["作った自分も俺だけど","笑う時だけいつもの顔だ"],"outro":"そこへ君の声がした","hook":["A borrowed color, freshly pressed","A heart that won't sit in my chest"]},{"id":"jp-019","lang":"jp","theme":"恋の始まり","title":"半分のイヤホン","v1":["片方ずつの小さな音","近づく理由を線がくれた"],"chorus":["同じところで笑えたら","この距離をもう少し続けよう","線の長さを使い切って","同じ響きのそばにいよう"],"v2":["歌が終わって無音になっても","誰も外そうと言わなかった"],"bridge":["感想よりも聞きたいのは","次も会えるかそれだけだ"],"outro":"巻き戻す指が触れた","hook":["A little wire, a shared refrain","We let the silence play again"]},{"id":"jp-020","lang":"jp","theme":"恋の始まり","title":"名前の呼び方","v1":["皆と同じ呼び方なのに","君の声だけ後に残る"],"chorus":["もう一度だけ呼んでみて","ありふれた名が変わるから","ありふれた音のひとつずつ","君が呼ぶたび光り出す"],"v2":["聞こえぬふりをしたことが","少しばかり恥ずかしかった"],"bridge":["特別な名はいらないよ","その声のまま呼んでほしい"],"outro":"今度はすぐに振り向く","hook":["A common name, a different sound","Your voice can turn the room around"]},{"id":"jp-021","lang":"jp","theme":"恋の始まり","title":"窓際の一席","v1":["窓際の席が空いていた","向かいの椅子を引いてみる"],"chorus":["ここに座るのが君ならば","今日の景色はそれでいい","窓の外など見えなくても","向かいの笑顔で明るくなる"],"v2":["混んできたねと君が笑う","本当はずっと空いててほしい"],"bridge":["言えない願いは小さいが","胸の場所だけ広く取る"],"outro":"二つの影に日が差した","hook":["The window has a perfect view","I keep on looking back at you"]},{"id":"jp-022","lang":"jp","theme":"恋の始まり","title":"読み終わらない本","v1":["勧められた本を開いて","同じ一頁で止まっている"],"chorus":["結末よりも知りたいのは","君が笑った場所なんだ","同じ頁を開きながら","違う景色を聞かせてよ"],"v2":["折った端には何もなくて","自分で目印をつけてみた"],"bridge":["同じ物語の中でも","違う君を見つけたい"],"outro":"続きを聞きに行こう","hook":["A different story on the page","Can put us on a smaller stage"]},{"id":"jp-023","lang":"jp","theme":"恋の始まり","title":"つり橋じゃないけど","v1":["普通の道を歩いている","隣の君は前を向く"],"chorus":["何も揺れてはいないのに","胸だけ足場をなくしてる","普通の道の普通の午後","君がいるだけで足が迷う"],"v2":["石につまずき笑われた","かっこつけるのをやめてみた"],"bridge":["強いふりよりこのままが","少し近くへ行ける気がした"],"outro":"歩幅が同じになっていた","hook":["The road is still, the air is clear","My balance changes with you here"]},{"id":"jp-024","lang":"jp","theme":"欲望と誘惑","title":"赤い靴の値札","v1":["閉店間際のガラス越し","履けない靴が光っている"],"chorus":["欲しいと言えば負けなのか","今夜は負けても構わない","役に立つかは聞いてない","胸が鳴るから見てるんだ"],"v2":["財布の中身を数え直す","明日の都合が顔を出す"],"bridge":["持っていない自分のままで","どこまで似合うか試したい"],"outro":"扉をまだ閉めないで","hook":["A pair of shoes behind the light","Can make the sensible feel slight"]},{"id":"jp-025","lang":"jp","theme":"欲望と誘惑","title":"鏡の女王","v1":["鏡の前で髪を直す","知らない俺が笑っていた"],"chorus":["見られるほどに変われるなら","視線を全部連れてきて","いつもの顔を脱ぐために","借りた輝きも使ってやる"],"v2":["襟元だけを派手に開ける","本音はそこへ隠しておく"],"bridge":["作り物でも熱くなれる","騙されたいのは俺の方だ"],"outro":"鏡が先に目をそらす","hook":["A mirror makes a brighter face","And leaves the hunger in its place"]},{"id":"jp-026","lang":"jp","theme":"欲望と誘惑","title":"最後の招待状","v1":["差出人のない招待状","金の文字だけよく読めた"],"chorus":["入っちゃいけない扉ほど","ノックの音が甘くなる","知らない夜の階段を","今日はこの足で上がりたい"],"v2":["階段の上で音がする","帰りの理由を下に置く"],"bridge":["何を失くすか知る前に","何があるのか見てみたい"],"outro":"指先が扉を押した","hook":["The stairs go up, the street stays low","I want to see before I know"]},{"id":"jp-027","lang":"jp","theme":"欲望と誘惑","title":"蜜の境界","v1":["一口だけと決めたのに","舌が続きを欲しがった"],"chorus":["甘い約束飲み干せば","渇きはもっと深くなる","欲しいと言える舌の上","まだ知らない味が残る"],"v2":["水を注いだグラスにも","同じ匂いが残っている"],"bridge":["満たされないと分かってても","選ぶこの手を隠さない"],"outro":"縁に残った蜜を舐める","hook":["The honey calls, the water waits","A wanting heart negotiates"]},{"id":"jp-028","lang":"jp","theme":"欲望と誘惑","title":"真昼の逃避行","v1":["仕事の電話が鳴っている","今日は空だけ広すぎる"],"chorus":["一日くらい盗ませて","誰のものでもない顔で","晴れた空から責められても","今日は俺の空でいたい"],"v2":["切符を二枚買いかけて","一枚だけを窓へ出した"],"bridge":["後で払うと言い聞かせる","自由の値段は知らないが"],"outro":"列車が影を追い越した","hook":["One stolen day, one open sky","The urgent voices drifting by"]},{"id":"jp-029","lang":"jp","theme":"欲望と誘惑","title":"触れない宝石","v1":["胸元で石が揺れている","話の続きを忘れてしまう"],"chorus":["見ているだけでいいなんて","優しい嘘が上手くなる","光に惹かれたふりをして","その目の奥を覗きたい"],"v2":["君が立つたび光が変わる","席を離れる理由を失う"],"bridge":["欲しいのは石の輝きか","それを着けてる君なのか"],"outro":"答えは唇で止まった","hook":["A little stone, a moving light","I cannot name the thing tonight"]},{"id":"jp-030","lang":"jp","theme":"欲望と誘惑","title":"夜を着替える","v1":["部屋を出るまで普通だった","階段ひとつで肩が変わる"],"chorus":["今夜の俺は借り物でいい","朝まで似合えばそれでいい","朝になったら戻れるなら","少し余計に遠くへ行こう"],"v2":["知らない名前を呼ばれても","振り向く速さは板についた"],"bridge":["嘘と本音の縫い目から","見たことのない熱が漏れる"],"outro":"上着をまだ脱ぎたくない","hook":["A different coat, a different walk","Can give the hidden self some talk"]},{"id":"jp-031","lang":"jp","theme":"欲望と誘惑","title":"銀のライター","v1":["火を借りただけのつもりが","指の形まで見てしまう"],"chorus":["小さな炎を消さないで","暗い方から近づくから","短い火なら消えるまで","長い目をして見ていよう"],"v2":["煙の向こうで目が合った","返す言葉を薄く吐いた"],"bridge":["危ないことは分かってる","だから時計を裏返した"],"outro":"銀の蓋が音を立てた","hook":["A silver click, a little heat","Two shadows nearly touch the street"]},{"id":"jp-032","lang":"jp","theme":"欲望と誘惑","title":"もう一皿だけ","v1":["腹はとっくに満ちている","目だけがまだ欲しがっている"],"chorus":["足りないものは皿じゃない","分かっていても頼んでしまう","終わったはずの満足を","新しい色が追い越してゆく"],"v2":["運ばれた甘い色を見て","さっきの満足を忘れた"],"bridge":["欲しがる自分を笑えたら","少しは味が分かるだろう"],"outro":"最後の匙を持ち直す","hook":["Another color on the plate","Can make enough a little late"]},{"id":"jp-033","lang":"jp","theme":"欲望と誘惑","title":"王様の試着室","v1":["借りた衣装に袖を通す","急に歩幅が大きくなる"],"chorus":["似合わないとは言わせない","鏡の中では王様だ","鏡の前の一歩だけ","大きな夢を着こなしてやれ"],"v2":["値札を見たら膝が戻る","元の自分が顔を出した"],"bridge":["買えない服に教えられた","欲しい姿はまだここにある"],"outro":"ポーズだけ持ち帰った","hook":["The borrowed crown can wait outside","I want a minute with my pride"]},{"id":"jp-034","lang":"jp","theme":"欲望と誘惑","title":"夏の裏口","v1":["正面玄関は閉まっていた","裏から明るい声がする"],"chorus":["誘いの言葉はなくていい","混ざってしまえば仲間だろ","名前がなくても手を叩ける","同じ熱なら入れてくれ"],"v2":["知らない歌に手を叩いた","名前を聞かれて少し止まる"],"bridge":["明日になれば消える縁でも","今の熱まで嘘じゃない"],"outro":"氷が溶ける音がした","hook":["An open rhythm through the door","Has room to take another four"]},{"id":"jp-035","lang":"jp","theme":"欲望と誘惑","title":"眠らない看板","v1":["灯りの下で影が伸びる","帰れる道ほど暗かった"],"chorus":["あと少しだけ起きていたい","何かになれそうなこの場所で","何にもなれずに帰る日も","欲しがる気持ちは持って帰る"],"v2":["何も起きずに店を出た","それでも歩き方が違う"],"bridge":["期待だけでも腹は膨れる","朝の空気で確かめよう"],"outro":"看板が先に眠りにつく","hook":["The signs stay bright, the roads stay near","I want to be somebody here"]},{"id":"jp-036","lang":"jp","theme":"嫉妬と執着","title":"消せない拍手","v1":["君が誰かに手を叩く","その横顔を見てしまった"],"chorus":["いい曲だったと言えるのに","言いたい言葉はそれじゃない","上手い下手より知りたいのは","君が振り向くその理由"],"v2":["家へ帰って同じ音を","探して何度も手が止まる"],"bridge":["負けたのは曲じゃなかった","君の視線を欲しがった"],"outro":"拍手の続きを消せない","hook":["The room applauds, I look at you","And hear the thing I cannot do"]},{"id":"jp-037","lang":"jp","theme":"嫉妬と執着","title":"留守番電話の三秒","v1":["用件だけで終わる声","後ろの笑いが耳に残る"],"chorus":["聞かなきゃいいのに戻してる","たった三秒が眠らせない","声の向こうへ耳を立て","自分の不安を聞いている"],"v2":["誰の声かと尋ねるほど","自分の声が小さくなる"],"bridge":["疑うために好きになった","わけじゃないのに指が戻る"],"outro":"再生の赤が点いた","hook":["The message stops, the doubt plays on","I hear a laugh that's almost gone"]},{"id":"jp-038","lang":"jp","theme":"嫉妬と執着","title":"二番目の椅子","v1":["いつもの席に誰かがいる","君は気づかず手を振った"],"chorus":["隣にいるのは俺なのに","遠い席から見ている気分","近さで気持ちを測るたび","離れた場所が増えてゆく"],"v2":["椅子を引く音が大きすぎた","笑って音を隠してみる"],"bridge":["席を決めても気持ちまでは","予約できない分かってる"],"outro":"椅子の脚を揃え直す","hook":["A chair can move across the room","And leave a distance in the gloom"]},{"id":"jp-039","lang":"jp","theme":"嫉妬と執着","title":"名前を伏せても","v1":["君の話の主語が減った","その分誰かが大きくなる"],"chorus":["知らないふりはできるけど","知らないままではいられない","言わない名前を知るよりも","言えない俺を見つめてよ"],"v2":["続きを聞かず皿を下げた","水の音だけ長くなる"],"bridge":["聞いた答えが怖いから","答えの前で怒ってしまう"],"outro":"蛇口を少し強く閉める","hook":["An absent name, a crowded thought","I make a question out of naught"]},{"id":"jp-040","lang":"jp","theme":"嫉妬と執着","title":"借りた言葉","v1":["昨日の君の口癖が","俺の知らない調子になる"],"chorus":["誰かの色に染まるなら","俺の言葉も残してよ","君の口から出る音に","俺の居場所を探してる"],"v2":["同じ言い方を試したら","君は不思議な顔をした"],"bridge":["似せるほどに離れてゆく","自分の声を思い出せ"],"outro":"普段の声で名を呼んだ","hook":["A phrase returns in someone’s tone","I want a sound to call our own"]},{"id":"jp-041","lang":"jp","theme":"嫉妬と執着","title":"片方だけの勝負","v1":["比べるなよと言ったあと","またあの人を数えている"],"chorus":["始めた覚えのない勝負","降りる場所さえ見つからない","誰も鳴らさぬ開始の鐘","俺だけずっと聞いている"],"v2":["褒められたことを書き出して","知らない余白に腹が立つ"],"bridge":["相手は俺を見ていない","鏡の前の一人相撲"],"outro":"紙を裏返してみた","hook":["A race that no one else can see","Has made a tired rival out of me"]},{"id":"jp-042","lang":"jp","theme":"嫉妬と執着","title":"写真の外側","v1":["写真の中で君が笑う","切れた端には誰がいた"],"chorus":["写っていない場所ばかり","見つめる俺を笑ってくれ","笑った瞬間そのものを","信じるだけでよかったのに"],"v2":["指で隠したその笑顔が","隠す前より気になった"],"bridge":["一枚の紙に映るより","君はずっと広いはずだ"],"outro":"写真を机に戻した","hook":["A frame can hold a single smile","And leave my mind another mile"]},{"id":"jp-043","lang":"jp","theme":"嫉妬と執着","title":"赤い丸印","v1":["暦の隅の赤い丸","俺と会わない日だと知る"],"chorus":["待たない顔を作るほど","時計の針が目に刺さる","君の暦を塗りつぶせば","俺の色まで濁ってしまう"],"v2":["同じ日に別の約束を","入れても心はそこにいる"],"bridge":["一日全部を奪うより","会える時間を大事にしろ"],"outro":"赤の隣へ青で書いた","hook":["A little circle marks a day","I cannot color you my way"]},{"id":"jp-044","lang":"jp","theme":"嫉妬と執着","title":"褒め言葉の棘","v1":["あいつはいいと言った君","悪気がないのは分かってる"],"chorus":["うなずくたびに棘が刺さる","俺にも同じ顔をして","いい奴だって分かるほど","嫌な自分が大きくなる"],"v2":["次に会ったら優しくされた","それすら少し腹が立った"],"bridge":["嫌いになるにはいい奴で","小さい俺だけ目立ってる"],"outro":"笑い方からやり直す","hook":["The praise is kind, the sting is small","I hate the way I hear it all"]},{"id":"jp-045","lang":"jp","theme":"嫉妬と執着","title":"覚えている数字","v1":["もう使わない電話番号","指だけ今も覚えている"],"chorus":["忘れたふりの上手な頭","手まで騙せはしないんだ","かけたいわけじゃないはずだ","触れたい昨日が指にある"],"v2":["途中で切って受話器を置く","鳴っていないのに耳を澄ます"],"bridge":["繋がることが答えじゃない","指をひとつずつほどいてく"],"outro":"掌を膝に伏せた","hook":["The fingers know what words deny","A number doesn't say goodbye"]},{"id":"jp-046","lang":"jp","theme":"嫉妬と執着","title":"同じ色の上着","v1":["あの人と同じ色を着た","偶然だよと先に言った"],"chorus":["似ていることが欲しくてさ","似ていない俺を隠してた","誰かの形を借りるたび","俺の輪郭が擦れてゆく"],"v2":["袖の長さが合わなくて","一日中ずっと触っていた"],"bridge":["似合う色まで捨てるほど","誰かの影は大きくない"],"outro":"明日はいつもの服にする","hook":["A borrowed shade, a longer sleeve","I try to look like I believe"]},{"id":"jp-047","lang":"jp","theme":"嫉妬と執着","title":"閉めた引き出し","v1":["君の忘れ物ひとつだけ","返せば理由がなくなってしまう"],"chorus":["渡せないまま大切にして","大切な方を遠ざける","物の小ささに隠れてた","大きな気持ちを出してみる"],"v2":["用があるから会おうと言って","用より先に笑ってしまう"],"bridge":["小さな物を握る手を","開けば話が始まるかも"],"outro":"引き出しをやっと開けた","hook":["A little thing behind the wood","Can hide a word misunderstood"]},{"id":"jp-048","lang":"jp","theme":"楽しい日常","title":"明日は午後から","v1":["時計を見たら見なきゃよかった","帰りの電車はとっくに寝てる"],"chorus":["明日は午後から午後からでいい","今夜の話はまだ途中","真面目な予定は少し待て","笑い話をもうひとつくれ"],"v2":["大きな皿の最後の一個","誰も取らずに笑っている"],"bridge":["予定は山ほどあるけれど","こんな夜には予約がない"],"outro":"会計の前で全員黙る","hook":["We miss the train, we split the fries","The morning catches up our lies"]},{"id":"jp-049","lang":"jp","theme":"楽しい日常","title":"焦げたトースト","v1":["煙の向こうで朝が来た","窓を開けたら隣も開いた"],"chorus":["焦げたところを削りながら","今日の機嫌を焼き直そう","予定にない色が付いても","朝まで失敗じゃないからさ"],"v2":["目玉焼きまで形が悪い","皿に載せたら顔に見えた"],"bridge":["上出来じゃない始まりに","笑えたならばそれでいい"],"outro":"珈琲だけはうまくできた","hook":["The toast went dark, the sun came through","A little smoke, a morning new"]},{"id":"jp-050","lang":"jp","theme":"楽しい日常","title":"雨宿り同盟","v1":["店の軒先四人ぶん","誰も傘など持っていない"],"chorus":["雨が止むまで付き合えよ","晴れても少し待ってやる","傘を持っても集まろうぜ","天気のせいだけじゃないだろう"],"v2":["意味のない話が続いて","止んだことまで忘れていた"],"bridge":["濡れた靴でも重くない","帰る時刻を分け合った"],"outro":"水たまりへ石を投げる","hook":["The rain runs out before we do","Another joke can see us through"]},{"id":"jp-051","lang":"jp","theme":"楽しい日常","title":"片道だけの遠足","v1":["行きの道だけ決めてきた","弁当の中はもう空っぽ"],"chorus":["帰りは知らない道にしよう","迷った分だけ話そうぜ","知ってる道を減らすより","知らない角を増やして帰る"],"v2":["畑の脇で犬に吠えられ","四人そろって道を変えた"],"bridge":["大きな旅じゃなくていい","知らない角がひとつあれば"],"outro":"家が見えたら腹が鳴る","hook":["One empty box, a different track","We brought no hurry for the back"]},{"id":"jp-052","lang":"jp","theme":"楽しい日常","title":"洗濯日和の旗","v1":["物干し竿に靴下並ぶ","片方だけが風で踊る"],"chorus":["立派な旗はいらないさ","洗いたての今日を掲げよう","風の向きなど変わっても","この色だけはよく乾く"],"v2":["探した片割れ椅子の下","昨日の俺が隠していた"],"bridge":["揃わない日もあるけれど","干せば同じ空の下だ"],"outro":"日向の匂いを取り込んだ","hook":["A row of socks can catch the breeze","No grand parade, no guarantees"]},{"id":"jp-053","lang":"jp","theme":"楽しい日常","title":"勝者のコロッケ","v1":["じゃんけんひとつで熱くなる","景品なんて小さいものだ"],"chorus":["勝った奴から食えばいい","冷める前なら皆勝ちだ","小さな勝ちを分けたなら","次は笑いで勝負しよう"],"v2":["負けた俺へ半分よこす","それなら勝負は何だった"],"bridge":["公平じゃなくたっていい","笑った数なら同じだろ"],"outro":"紙袋まで温かい","hook":["A little win, a shared hot bite","Can make a very ordinary night"]},{"id":"jp-054","lang":"jp","theme":"楽しい日常","title":"休日の寝癖","v1":["昼に起きたら日が高い","鏡の中で草が伸びた"],"chorus":["寝癖も今日は自由にしよう","予定のない頭でいよう","きちんとしない顔のまま","ちゃんと休むをやってみる"],"v2":["外へ出るなら帽子を探す","見つからなくてそのまま出た"],"bridge":["気にするほどのことじゃない","誰も俺だけ見ていない"],"outro":"風が代わりに直してく","hook":["My hair can take the morning off","There is no meeting with the clock"]},{"id":"jp-055","lang":"jp","theme":"楽しい日常","title":"缶蹴りの延長戦","v1":["広場の缶を起こしてみる","大人の靴が円を描いた"],"chorus":["もう一回が終わらない","暗くなるまで名前を呼ぼう","隠れきれない大きな影","見つけたらまた走ればいい"],"v2":["息を切らして隠れている","昔より影がはみ出した"],"bridge":["背が伸びたって見つかれば","同じ顔して走り出す"],"outro":"街灯が審判を始める","hook":["The shadows grew, the rules stayed thin","The streetlight tells us to begin"]},{"id":"jp-056","lang":"jp","theme":"楽しい日常","title":"小銭の海","v1":["ポケット全部をひっくり返す","意外と遠くへ行けそうだ"],"chorus":["小さな硬貨を寄せ合って","大きな予定を買いに行こう","高いものほど楽しいなんて","今日の財布は言ってない"],"v2":["店の前まで来たところで","何を買うのかまた揉めた"],"bridge":["決まらないのが楽しくて","店員までが笑っている"],"outro":"まずは飲み物四つくれ","hook":["A pocket emptied on the ground","Can buy the talk that goes around"]},{"id":"jp-057","lang":"jp","theme":"楽しい日常","title":"料理の名前は後で","v1":["鍋へ余りを全部入れた","色だけ見れば強そうだ"],"chorus":["名前のない飯を食おう","うまけりゃ明日も思い出す","苦い顔まで分け合って","うまくなるまで塩をくれ"],"v2":["一口目から全員黙る","塩を入れたら話が戻る"],"bridge":["失敗だって分けて食えば","ひとつの話になるんだな"],"outro":"鍋の底まできれいだね","hook":["A little salt, another taste","There isn't much we need to waste"]},{"id":"jp-058","lang":"jp","theme":"楽しい日常","title":"昼寝の観客","v1":["芝生の上へ寝転がる","雲の形に意見が割れた"],"chorus":["何もしないをやっている","急かす声なら風に乗せろ","何かにならない午後だって","確かに俺達がここにいる"],"v2":["隣の寝息が聞こえ始め","話の途中を鳥がさらう"],"bridge":["答えを出さない時間にも","四人ぶんの場所がある"],"outro":"靴を枕にもう少し","hook":["The clouds can argue with the sun","We have a lot of nothing done"]},{"id":"jp-059","lang":"jp","theme":"楽しい日常","title":"くだらない大賞","v1":["一番ひどい冗談に","今日の大賞あげると言った"],"chorus":["くだらないこと守りたい","腹がよじれる今のうちに","立派なことでは届かない","腹の底まで揺らしてくれ"],"v2":["誰も審査をしてなくて","最後は自分で自分を指す"],"bridge":["笑う理由は薄くても","笑った時間は薄くない"],"outro":"受賞の言葉でまた滑る","hook":["The worst joke takes the little prize","We laugh until the daylight cries"]},{"id":"jp-060","lang":"jp","theme":"生活への違和感","title":"壁紙の空","v1":["壁紙の空はいつでも晴れる","窓を閉めても雨は降らない"],"chorus":["この青を剥がしたい","本当の雨に濡れたい","汚れた壁にも風が来る","飾らない空を入れてくれ"],"v2":["笑顔の写真を貼り替えるたび","誰の部屋だか分からなくなる"],"bridge":["めくれた角へ指をかける","そこから風が入ってくる"],"outro":"窓を開けたら曇っていた","hook":["A painted blue, a lifted seam","I need the weather, not the dream"]},{"id":"jp-061","lang":"jp","theme":"生活への違和感","title":"整列した影","v1":["朝の通路で列が伸びる","影まで同じ向きを向く"],"chorus":["半歩だけでもずれてみろ","違う景色が足元にある","揃った影の端っこで","違う形が息をしている"],"v2":["隣の靴とぶつかったあと","互いに少し頭を下げた"],"bridge":["並べない奴が邪魔なのか","狭い通路が悪いのか"],"outro":"空いた方へ歩いてみる","hook":["A half-step out, a different view","There is a body in this queue"]},{"id":"jp-062","lang":"jp","theme":"生活への違和感","title":"便利な返事","v1":["はいと言うのが早くなって","話の中身が遅れて届く"],"chorus":["便利な声で呼ばないで","俺にも考える間をくれ","上手く頷く首よりも","考える顔を戻したい"],"v2":["今日も頼まれ笑ったあと","一人で机を拭いていた"],"bridge":["断ることも仕事なら","最初に俺へ頼みたい"],"outro":"返事の前に息を吸う","hook":["The useful yes, the missing thought","I owe myself the time I bought"]},{"id":"jp-063","lang":"jp","theme":"生活への違和感","title":"新品の檻","v1":["鍵のかからぬ部屋なのに","出ていく理由を探している"],"chorus":["居心地だけで決めるなよ","柔らかな壁も壁なんだ","居心地のいい場所だから","立つ力まで預けたくない"],"v2":["欲しかった椅子に深く座る","立つ時の足が重くなる"],"bridge":["満たされたまま息が詰まる","贅沢だって苦しくなる"],"outro":"扉は今も開いている","hook":["A softer wall can still be there","A perfect chair can steal the air"]},{"id":"jp-064","lang":"jp","theme":"生活への違和感","title":"判子の顔","v1":["書類の隅に名前を押す","同じ顔だけ増えてゆく"],"chorus":["赤い丸からはみ出した","俺の声はどこへ行く","押せば終わりの名前より","呼べば振り向く俺でいたい"],"v2":["印肉の蓋が閉まらない","指についた色を見ている"],"bridge":["名乗ることまで代わらせて","楽になったと思っていた"],"outro":"今日は自分で字を書いた","hook":["A little red upon the sheet","Is not a life upon its feet"]},{"id":"jp-065","lang":"jp","theme":"生活への違和感","title":"透明な昼休み","v1":["席を離れてパンをかじる","誰にも呼ばれない十分間"],"chorus":["ここにいるのを忘れてくれ","消えたいわけではないけれど","時計が俺を呼ぶまでは","何の役でもないままで"],"v2":["窓へ映った人の群れに","一人くらいの隙間が見えた"],"bridge":["役目のない顔のままで","しばらく空を見ていたい"],"outro":"包み紙を小さく畳む","hook":["No role to play, no name to call","I need a minute being small"]},{"id":"jp-066","lang":"jp","theme":"生活への違和感","title":"借り物の口癖","v1":["皆が言うから口にした","意味を聞かれて言葉が止まる"],"chorus":["俺の言葉はどれだろう","使い古して探している","流行りの声が抜けたあと","不格好な息が残ってる"],"v2":["家の鏡へ話しかけた","少し不格好な声がした"],"bridge":["うまくなくてもこの調子を","誰かの口へ返さない"],"outro":"自分で言って笑ってみた","hook":["The borrowed words begin to fade","A stranger voice is how I'm made"]},{"id":"jp-067","lang":"jp","theme":"生活への違和感","title":"売り場の幸福","v1":["幸せそうな箱が並ぶ","置く場所だけが増えていく"],"chorus":["買ったはずの自由から","片づけの手間が溢れ出す","欲しいと言ったあの日から","置き場所ばかり増えてゆく"],"v2":["欲しいものだけ数えたあと","いらないものが残っていた"],"bridge":["何もない棚を作ったら","窓から光が奥へ来た"],"outro":"空いた場所には何も置かず","hook":["A shelf of things I used to want","Can make the empty corner haunt"]},{"id":"jp-068","lang":"jp","theme":"生活への違和感","title":"笑顔の練習台","v1":["聞きたいことを聞かれない","答えやすいことだけ上手い"],"chorus":["笑顔の裏も俺だから","そこまで見ても逃げないで","役に立たない表情も","全部まとめて俺なんだ"],"v2":["口の形を鏡で戻す","普通の顔が分からない"],"bridge":["嫌われぬよう磨くほど","誰がいるのか薄くなる"],"outro":"今日は黙って頷いた","hook":["The practiced smile, the waiting face","I need them both to have a place"]},{"id":"jp-069","lang":"jp","theme":"生活への違和感","title":"揃いすぎた窓","v1":["夜の建物遠くから","同じ明かりが並んで見える"],"chorus":["あの窓ごとに違う人","同じ白さで隠さないで","灯りの数を数えるより","その奥の夜を思っている"],"v2":["ひとつ灯りが消えるたび","別の暮らしが目に浮かぶ"],"bridge":["数えるほどに増えるのは","数字じゃなくて知らぬ顔"],"outro":"窓の向こうも夜なんだ","hook":["The windows shine the same pale white","A thousand rooms, a thousand nights"]},{"id":"jp-070","lang":"jp","theme":"生活への違和感","title":"昨日の予告編","v1":["明日のためと言われ続け","今日がいつでも準備になる"],"chorus":["本編はいつ始まるんだ","予告ばかりじゃ生きられない","明日の俺にも悪いけど","今日の俺にも席をくれ"],"v2":["後で使うとしまったものを","一つずつ机へ戻してみる"],"bridge":["立派な未来へ送るより","今の俺にも使わせろ"],"outro":"取っておいた靴を履いた","hook":["The trailer runs, the day slips through","I need a part that's happening too"]},{"id":"jp-071","lang":"jp","theme":"生活への違和感","title":"音量のない怒り","v1":["大きな声は出せなかった","それで納得したことになる"],"chorus":["黙ったことを丸にするな","返事はまだここにある","大声だけの物差しなら","測れないものがここにある"],"v2":["紙の端から言葉を書いて","折らずに机へ置いてきた"],"bridge":["聞き取れないなら近づけよ","叫ぶ力で決めないで"],"outro":"小さな字でも消せはしない","hook":["A quiet line, a steady hand","Can make a place for me to stand"]},{"id":"jp-072","lang":"jp","theme":"自信と挑戦","title":"天井より高く","v1":["見上げる先に梁がある","その向こうまで声を投げる"],"chorus":["天井より高く行け","届いた場所で止まるなよ","限界なんて名札より","今の声の行く先を見ろ"],"v2":["一度届いた音の先に","まだ聞こえない隙間がある"],"bridge":["ゴールの旗など見当たらない","胸の速さが道を教える"],"outro":"空には蓋がなかった","hook":["Higher than the line I see","There is another note in me"]},{"id":"jp-073","lang":"jp","theme":"自信と挑戦","title":"白紙の一番上","v1":["何も書かないノートほど","間違えるのが怖かった"],"chorus":["一行目なら汚してしまえ","続きを書く場所はまだある","書かなかったら消えもしない","残らないまま終わるだけだ"],"v2":["消し跡ばかり増えた紙に","初めて言葉を残してみた"],"bridge":["きれいなままの可能性より","汚れた今日を選びたい"],"outro":"二行目には迷わなかった","hook":["A dirty word upon the white","Can give the next one room to write"]},{"id":"jp-074","lang":"jp","theme":"自信と挑戦","title":"助走はここまで","v1":["準備ばかりが上手くなって","踏み切る場所が後ろへずれる"],"chorus":["助走はここまで飛んでみろ","向こうの風に触れてこい","できる自分を待つよりも","やってる自分を始めたい"],"v2":["足が離れた短い間","考えることがなくなった"],"bridge":["遠くへ届かなくたって","線の向こうに着地した"],"outro":"次の線を自分で引く","hook":["The running stops, the open air","Has something new to teach me there"]},{"id":"jp-075","lang":"jp","theme":"自信と挑戦","title":"最初の客は俺","v1":["誰も聴かない部屋の中","自分の耳だけ残ってる"],"chorus":["まずこの俺を振り向かせろ","よそ見する暇をなくしてやれ","よその拍手を借りるより","俺が欲しがる響きをくれ"],"v2":["録っては聴いて首をかしげ","急に一度だけ笑えたんだ"],"bridge":["褒められる日を待つ前に","好きだと言える音にしろ"],"outro":"もう一度だけ回してみる","hook":["The room is small, the ear is mine","I want a sound that makes it shine"]},{"id":"jp-076","lang":"jp","theme":"自信と挑戦","title":"向かい風の値打ち","v1":["坂の途中で風が来た","下りる方へ背中を押す"],"chorus":["楽な方角は知っている","それでも上へ顔を向けろ","逆さの風に背を向けず","踏んだ土まで覚えていこう"],"v2":["帽子を押さえ歩幅を狭め","進んだ距離を振り返った"],"bridge":["速さでだけは測れない","逆らう一歩の重さがある"],"outro":"風の匂いが変わってきた","hook":["The headwind knows the weight I take","One honest step for my own sake"]},{"id":"jp-077","lang":"jp","theme":"自信と挑戦","title":"手の届く星","v1":["星になれよと言われても","空まで届く腕はない"],"chorus":["届く場所から光らせろ","指先ひとつで夜は変わる","遠い空へと願うより","そばの暗さへ手を伸ばせ"],"v2":["壊れた灯りを直してみた","隣の顔まで明るくなる"],"bridge":["大きな名前はいらないさ","目の前だけは照らせるだろ"],"outro":"窓がひとつ光を返す","hook":["A little lamp beside a face","Can make a universe of space"]},{"id":"jp-078","lang":"jp","theme":"自信と挑戦","title":"予備のない鍵","v1":["合わない鍵を何度も回す","違う扉だとやっと気づく"],"chorus":["開かないなら探してみろ","お前に合った入口を","壊すだけしか知らなかった","叩けば応える場所もある"],"v2":["壁の向こうで声がした","ノックの仕方を変えてみる"],"bridge":["一つの鍵で全部開く","そんな話はもういらない"],"outro":"別の扉が少し開く","hook":["A different knock, another door","Can tell me what this key is for"]},{"id":"jp-079","lang":"jp","theme":"自信と挑戦","title":"勝負服は普段着","v1":["特別な日と決めた朝","いつもの服へ腕を通す"],"chorus":["背伸びの分だけ歩きにくい","この格好でやってやる","背中に余計な羽根はいらない","この重さなら歩けるだろう"],"v2":["袖の擦り切れ目に入っても","直す手間より先に出かけた"],"bridge":["慣れた自分を連れてゆけ","今日の相手は今日の俺"],"outro":"靴の音だけ大きくなる","hook":["No borrowed wings upon my back","These worn-out clothes can take the track"]},{"id":"jp-080","lang":"jp","theme":"自信と挑戦","title":"高い棚の箱","v1":["子どもの頃は見えなかった","棚の上へ手が届いた"],"chorus":["できないままで覚えていた","俺の大きさ測り直せ","届かぬ頃の目盛りから","今の自分を解き放て"],"v2":["箱の中身は空だったが","腕を伸ばしたことは残る"],"bridge":["次に届かぬ場所を見たら","昔の俺で決めつけるな"],"outro":"椅子を使わず箱を戻す","hook":["An empty box above my head","Can hold the height I never read"]},{"id":"jp-081","lang":"jp","theme":"自信と挑戦","title":"二度目の応募","v1":["戻った封筒捨てられず","机の下に置いていた"],"chorus":["断られたのはあの日の俺","今日の名前でもう一度","同じ宛先違う俺","昔の封筒では届かない"],"v2":["同じ宛先を書き直す","前より少し太い文字だ"],"bridge":["返事を変えろと言う前に","渡す中身を変えてきた"],"outro":"切手の端を押さえつける","hook":["The same address, a different hand","A better reason in the stamp"]},{"id":"jp-082","lang":"jp","theme":"自信と挑戦","title":"負け惜しみの続き","v1":["負けた直後に口にした","次は勝つから覚えとけ"],"chorus":["捨て台詞にはしたくない","続きの汗で言い直す","言った言葉に追われるなら","追いつく足へ変えてしまえ"],"v2":["誰も見ていない場所へ戻る","悔しさだけなら冷めてゆく"],"bridge":["言った自分を追い越すため","今日の小さな壁を越える"],"outro":"次と呼んでた日が近づく","hook":["I made a vow beneath my breath","Now every little try has depth"]},{"id":"jp-083","lang":"jp","theme":"自信と挑戦","title":"道具箱の夢","v1":["古い道具を並べたら","どれも俺より傷が多い"],"chorus":["新品だけが始まりじゃない","使えるものから作ってやれ","足りないものを数えたあと","使える手まで隠すなよ"],"v2":["曲がった釘を打ち直した","少し斜めの台ができた"],"bridge":["完璧までを待っていたら","乗せたい夢が錆びてしまう"],"outro":"その台からならよく見える","hook":["A crooked nail, a useful hand","Can build a place for dreams to land"]},{"id":"jp-084","lang":"jp","theme":"迷いと不安","title":"笑う順番","v1":["皆が笑って少し遅れる","声を重ねて間に合わせた"],"chorus":["俺は何に笑ったんだ","口の形から確かめる","遅れた笑いを責めるより","本当の顔を探してみる"],"v2":["一人になると静かすぎて","さっきの声が遠く聞こえる"],"bridge":["合わせることが悪くはない","消えるところまで行かないで"],"outro":"自分の息で笑ってみる","hook":["A second late, a borrowed grin","I want the laugh that starts within"]},{"id":"jp-085","lang":"jp","theme":"迷いと不安","title":"空席の重さ","v1":["向かいの椅子が空いている","まだ誰も座らぬだけなのに"],"chorus":["いない誰かを数えてる","今ここにいる俺を忘れて","待つことだけが俺じゃない","座ってる影にも名前がある"],"v2":["扉の音へ目が動いて","入った風に肩を落とした"],"bridge":["来るかどうかは決められない","俺の席まで立たないで"],"outro":"背もたれへ体を預ける","hook":["The empty chair, the waiting air","Can't take the person sitting here"]},{"id":"jp-086","lang":"jp","theme":"迷いと不安","title":"寝返りの地図","v1":["眠れぬ夜に向きを変える","天井だけが動かない"],"chorus":["どこへ寝返り打てばいい","明日の位置が見つからない","答えのないこの夜にも","眠れぬ俺の居場所はある"],"v2":["枕の裏は少し冷たい","その小ささに救われている"],"bridge":["全部の答えはいらないか","次の呼吸ならできそうだ"],"outro":"目覚ましより先に鳥が鳴く","hook":["The room stays still, I turn again","One breath can take me back to ten"]},{"id":"jp-087","lang":"jp","theme":"迷いと不安","title":"褒められた翌朝","v1":["褒められた声が耳に残る","同じことがもうできない"],"chorus":["昨日の俺を待たないで","今日は今日から始めさせて","同じ高さへ跳べなくても","動く足まで嘘じゃない"],"v2":["録音の中はうまくいく","止めれば部屋が広すぎた"],"bridge":["一度の出来で全部決める","そんな重さを下ろしたい"],"outro":"小さい音からやり直す","hook":["A lucky night, a worried day","I start a smaller song to play"]},{"id":"jp-088","lang":"jp","theme":"迷いと不安","title":"波のない港","v1":["船は揺れずに繋がれて","安心の分だけ苔がつく"],"chorus":["怖いのは海か陸なのか","ほどけぬ結び目見ている","安心だけじゃ足りないと","揺れない胸が言っている"],"v2":["風が変わって旗が鳴る","出る理由まで待っていた"],"bridge":["帰れる場所があるのなら","離れることもできるだろ"],"outro":"綱へ伸ばした手が止まる","hook":["A quiet boat, a waiting tide","I need to hear the world outside"]},{"id":"jp-089","lang":"jp","theme":"迷いと不安","title":"似合わない拍子","v1":["同じ拍を数えながら","一つ先へ足が出てしまう"],"chorus":["合わせたいのか合わせられぬか","自分の足へ聞いてみる","誰かに追いつく息じゃなく","自分の息で並びたい"],"v2":["遅れてみたら今度は早い","焦る気持ちが音を追い越す"],"bridge":["誰かの歩幅を借りるより","一緒に探す速さがある"],"outro":"隣へ小さく声をかける","hook":["I lose the beat, I find a friend","We have a tempo we can mend"]},{"id":"jp-090","lang":"jp","theme":"迷いと不安","title":"開封前の封筒","v1":["返事が来たのに開けられず","湯だけ沸かして座っている"],"chorus":["知らないままなら傷つかない","進めもしないと知っている","薄い紙より重いのは","読んでない俺の想像だ"],"v2":["指をかけたら紙が裂けた","思ったよりも軽い音だ"],"bridge":["良くても悪くてもその先で","今日の続きを作るしかない"],"outro":"湯気の向こうで文字を追う","hook":["A piece of paper holds the fear","Until I let the words appear"]},{"id":"jp-091","lang":"jp","theme":"迷いと不安","title":"階段の途中","v1":["何階まで来たか忘れた","上も下も同じ扉だ"],"chorus":["高く来たのか迷ったのか","息の荒さじゃ分からない","休むためにも窓がいる","息を整えまた数えよう"],"v2":["踊り場の窓を押してみた","見覚えのある道が見えた"],"bridge":["止まる時間も登る途中","焦って階を飛ばすなよ"],"outro":"窓を閉めて数え直す","hook":["A little window on the stair","Can tell me where I really am"]},{"id":"jp-092","lang":"jp","theme":"迷いと不安","title":"薄い氷の声","v1":["大丈夫だと返すたび","足元だけが透けてくる"],"chorus":["割れる音まで待たないで","重いと言えるうちに言え","重たいことを言える場所","その上にこそ立っていたい"],"v2":["何も言わずに置いた荷物","肩が軽くて驚いていた"],"bridge":["強い顔だけ覚えるより","弱い時にも名乗りたい"],"outro":"誰かが荷物へ手を伸ばす","hook":["The weight is real, the voice is thin","I need a place to let it in"]},{"id":"jp-093","lang":"jp","theme":"迷いと不安","title":"明日の輪郭","v1":["予定は紙に埋まっている","その中に俺が見えなくなる"],"chorus":["忙しさなら数えられる","望むことまで埋めないで","空いた時間が問いかける","俺は何をしたかったんだ"],"v2":["一つ断って空けた枠に","何を書こうか迷っている"],"bridge":["何もないのは怖いけど","そこから選べることもある"],"outro":"空白のまま閉じてみた","hook":["An empty square can ask me why","I keep on letting days go by"]},{"id":"jp-094","lang":"jp","theme":"迷いと不安","title":"遠い自分宛","v1":["未来の俺へ手紙を書く","偉そうなことは書けなかった"],"chorus":["うまくやれとは言わないよ","ちゃんと困って歩いてくれ","立派な返事はいらないが","生きてる言葉で返してくれ"],"v2":["封をする前もう一度読み","一行だけを足してみた"],"bridge":["ここにいる俺を忘れても","あの頃を笑って済ますなよ"],"outro":"日付を少し大きく書いた","hook":["A letter sent across the years","Can hold the shape of smaller fears"]},{"id":"jp-095","lang":"jp","theme":"迷いと不安","title":"追い越した靴音","v1":["後ろの足音近づいて","横へ来た途端早足になる"],"chorus":["急ぐ理由もないくせに","誰かの速さで息を切らす","知らない相手に急かされて","知ってる道まで見失うな"],"v2":["角を曲がれば人は消えた","自分の行き先さえ過ぎてた"],"bridge":["勝手な勝負を降りたあと","戻る道にも空はある"],"outro":"ゆっくり靴を鳴らしてみる","hook":["A stranger's pace, a borrowed race","I need my feet back in their place"]},{"id":"jp-096","lang":"jp","theme":"記憶と郷愁","title":"夏の蛇口","v1":["校庭の隅の蛇口だけ","今でも少し下を向いてる"],"chorus":["あの冷たさを覚えてる","名前より先に喉が知ってる","小さな手からこぼれた夏","大きな今にも冷たく届く"],"v2":["手で受けた水がこぼれた","大きくなっても下手なままだ"],"bridge":["戻るためではなく来たんだ","今の足でも触れられる"],"outro":"水を止めれば蝉が聞こえる","hook":["The water knows a smaller hand","And takes me where I used to stand"]},{"id":"jp-097","lang":"jp","theme":"記憶と郷愁","title":"消えた駄菓子屋","v1":["店のあった場所が駐車場","白い線だけ引いてある"],"chorus":["何もないとは言わないよ","ここで迷った十円がある","買えるものなら増えたけど","あの迷い方は買えないな"],"v2":["買えなかった菓子の形を","今さら二人で思い出す"],"bridge":["大きな金を持った今も","あの迷いだけ買い直せない"],"outro":"ポケットの硬貨を鳴らした","hook":["A parking line, a missing store","I had so little, wanted more"]},{"id":"jp-098","lang":"jp","theme":"記憶と郷愁","title":"背丈の線","v1":["柱に残る鉛筆の線","昔の俺が低く笑う"],"chorus":["伸びた分だけ離れても","この線から歩いてきたんだ","見えないところで伸びた分","この目盛りでは分からない"],"v2":["指を合わせて立ってみる","目の高さには何もなかった"],"bridge":["測れなくなった今の俺","どこで伸びたか考えてみる"],"outro":"一番上へ日付を書く","hook":["A little mark beside the frame","Remembers how I grew my name"]},{"id":"jp-099","lang":"jp","theme":"記憶と郷愁","title":"折れたクレヨン","v1":["箱の底から色が出る","短い青だけよく減ってる"],"chorus":["どんな空でも描けた手","今も手首の先にある","短くなった好きな色","なくなるまでは描けるだろう"],"v2":["白い紙へ力を入れた","折れた先でも色は出ていた"],"bridge":["上手な絵にはならないが","好きな色ならまだ選べる"],"outro":"青が爪の端に残る","hook":["A broken blue can draw the sky","Until the last small color dries"]},{"id":"jp-100","lang":"jp","theme":"記憶と郷愁","title":"呼び鈴の音","v1":["昔の家の前を通る","違う名前が掛かっている"],"chorus":["押さない鈴が鳴り出した","俺の中だけ昔の音だ","鳴らさぬままでも聞こえてる","あの日ここへ帰った音が"],"v2":["知らない人が扉を開け","会釈をしてから通り過ぎた"],"bridge":["同じ場所でも別の暮らし","俺の記憶を押しつけない"],"outro":"角まで歩いて振り返る","hook":["I leave the bell, I hear it ring","A different house, a familiar thing"]},{"id":"jp-101","lang":"jp","theme":"記憶と郷愁","title":"古い運動靴","v1":["押し入れの奥で見つけた","小さな靴に土がついてる"],"chorus":["あの頃どこへ急いでた","踵の穴から聞いてみる","走る理由は変わっても","土の匂いは忘れない"],"v2":["履けない靴を並べながら","今の足にも泥を見つけた"],"bridge":["変わった形の中にある","変わらぬ癖が可笑しかった"],"outro":"土だけ外で払ってやる","hook":["A hole beneath a smaller heel","Still knows the roads I used to feel"]},{"id":"jp-102","lang":"jp","theme":"記憶と郷愁","title":"テープの裏の声","v1":["無音の後に笑いが入る","録るつもりのない俺の声"],"chorus":["残すと決めたものよりも","残ってしまった俺が近い","気取らぬ顔が見えるほど","雑な笑いが近くなる"],"v2":["巻き戻す度少し照れて","そのまま消さずに聴いている"],"bridge":["大事な顔をしていない","こんな時にも生きていた"],"outro":"笑いの途中でテープが止まる","hook":["A careless laugh behind the track","Can bring an unposed person back"]},{"id":"jp-103","lang":"jp","theme":"記憶と郷愁","title":"匂いの帰り道","v1":["雨の土の匂いがして","知らない道で足が止まる"],"chorus":["帰る場所より先に帰る","鼻の奥からあの夏が来る","見知らぬ街で目を閉じる","昔の雨が頬を撫でる"],"v2":["曲がった先は別の街だ","知ってるはずが一つもない"],"bridge":["思い出だけを連れてゆく","道は今いる方へ続く"],"outro":"雨粒を肩から払った","hook":["The smell of rain, a different town","My younger feet come walking round"]},{"id":"jp-104","lang":"jp","theme":"記憶と郷愁","title":"小さな自転車屋","v1":["油の匂いが戸口にある","低い椅子だけ昔のまま"],"chorus":["直したものが走ってゆく","その背中を覚えていたい","軽い車輪を送り出す","あの人の手を覚えていたい"],"v2":["空気を借りて頭を下げる","昔より楽にペダルが回る"],"bridge":["変わらぬものがひとつあれば","変わった俺も確かめられる"],"outro":"ベルを一度だけ鳴らした","hook":["A little oil, a wheel set free","The hands that helped are still with me"]},{"id":"jp-105","lang":"jp","theme":"記憶と郷愁","title":"秘密基地の鍵","v1":["鍵をかけてもいないのに","合言葉だけ厳しかった"],"chorus":["守っていたのは物じゃなく","仲間に入れるその一言","壁より強い合言葉","今の俺でも覚えている"],"v2":["古い茂みは刈られていた","遠くの道がよく見える"],"bridge":["囲った場所はなくなっても","呼び合う言葉は持っている"],"outro":"あの合言葉を呟いた","hook":["The walls are gone, the word remains","I try its sound against the change"]},{"id":"jp-106","lang":"jp","theme":"記憶と郷愁","title":"放課後の影踏み","v1":["日が傾くほど背が伸びた","影だけ先に大人になった"],"chorus":["追いつきたくて走った道","今は歩いて見えるものがある","先に大きくなった影","今は並んで歩いてゆこう"],"v2":["長い影を踏んでみたら","誰のものでもなかったんだ"],"bridge":["急いだ自分を笑わない","走った分だけここへ来た"],"outro":"影の隣を歩いて帰る","hook":["My shadow grew before I did","It holds a little running kid"]},{"id":"jp-107","lang":"jp","theme":"記憶と郷愁","title":"初めての遠出","v1":["地名をひとつ覚えただけで","遠くへ来たと信じていた"],"chorus":["狭い地図でも広かった","知らないものを見に行く目には","近い遠いを決めるのは","距離だけじゃないあの目だろう"],"v2":["今ならすぐに着く距離でも","あの一日を短くできない"],"bridge":["大きな旅を数えるより","驚く心を持っていたい"],"outro":"駅名を声にして読んだ","hook":["A tiny trip, a world unknown","The distance wasn't miles alone"]},{"id":"jp-108","lang":"jp","theme":"そばにいる人への感謝","title":"黙って置いた湯飲み","v1":["話したくない顔をしたら","湯飲みがひとつ前へ来た"],"chorus":["何も聞かずにいてくれて","言える言葉が戻ってくる","急かされないから話せるんだ","湯気の向こうで待っていて"],"v2":["冷めかけたお茶を飲みながら","今日はひどいとやっと言えた"],"bridge":["答えを先に置くよりも","空いた場所をくれたんだね"],"outro":"今度は俺がお湯を沸かす","hook":["The cup went down, the silence stayed","It let the frightened words be made"]},{"id":"jp-109","lang":"jp","theme":"そばにいる人への感謝","title":"貸した背中","v1":["荷物の紐が切れたとき","誰かの手だけすぐ動いた"],"chorus":["助けてと言うその前に","見ていてくれた背中がある","重たいものを持ったまま","振り返ってくれた人がいる"],"v2":["礼を言っても軽く笑って","別の話を始めてしまう"],"bridge":["返す日付は決めなくていい","困った時には俺を呼べ"],"outro":"片方ずつで持ってゆこう","hook":["You took the weight without a speech","I learned how far a hand can reach"]},{"id":"jp-110","lang":"jp","theme":"そばにいる人への感謝","title":"二杯目の水","v1":["言いすぎたあと黙った席","君が水だけ足してくれた"],"chorus":["仲直りなら急がなくていい","同じ卓にはまだいられる","上手く謝るその前に","同じ時間を飲んでいよう"],"v2":["ぬるい水をゆっくり飲んで","ごめんの前に息をついた"],"bridge":["大きな言葉が出ない日も","小さな手間は届くんだな"],"outro":"今度は君の杯へ注ぐ","hook":["A little water, time to breathe","We have a table not to leave"]},{"id":"jp-111","lang":"jp","theme":"そばにいる人への感謝","title":"待っていた玄関","v1":["遅くなったと鍵を回す","廊下の灯りがついていた"],"chorus":["ただいまだけじゃ足りないが","まずはいつもの声で帰ろう","帰れる場所をくれた人へ","慣れた言葉を丁寧に言う"],"v2":["怒ると思った顔が眠い","明日の話は後にしよう"],"bridge":["待たせることに慣れた俺","待つ人まで慣れさせたくない"],"outro":"靴を揃えて灯りを消す","hook":["A hallway light, a pair of shoes","Some ordinary things to choose"]},{"id":"jp-112","lang":"jp","theme":"そばにいる人への感謝","title":"下手な励まし","v1":["うまい言葉が出なかったと","君は自分で照れていた"],"chorus":["それで十分なんだって","今の声でもう伝わってる","探してくれたその時間","言葉の隙間に見えている"],"v2":["気の利く返事を考えるより","二人で少し笑ってみた"],"bridge":["上手く言うため黙るより","下手でも俺を呼んでくれ"],"outro":"背中の重さが軽くなる","hook":["The words came wrong, the care came through","I felt the time you gave me too"]},{"id":"jp-113","lang":"jp","theme":"そばにいる人への感謝","title":"合鍵の重さ","v1":["小さな鍵を渡された","金属よりも意味が重い"],"chorus":["開く扉が増えたんじゃない","戻れる場所が増えたんだ","小さな音が混ざるだけで","帰り道まで変わってくる"],"v2":["なくさぬように輪へ通した","いつもの鍵と音が混ざる"],"bridge":["自由なままで帰れること","当たり前にはしたくない"],"outro":"掌の中で温まる","hook":["A little key, a warmer hand","Can change the place I mean to land"]},{"id":"jp-114","lang":"jp","theme":"そばにいる人への感謝","title":"縫い目の内側","v1":["取れたボタンが戻っていた","誰が直したか聞かなくても"],"chorus":["目立たぬところで支えてる","そんな手つきを覚えたい","見えない仕事の一本が","今日の俺を繋いでいる"],"v2":["外へ出る前もう一度触る","糸の色だけ少し違った"],"bridge":["完全に元へ戻すより","君の跡がある方がいい"],"outro":"襟を正して礼を言う","hook":["A thread of slightly different blue","Can hold a day and carry you"]},{"id":"jp-115","lang":"jp","theme":"そばにいる人への感謝","title":"同じ傘の速度","v1":["俺が急ぐと肩が濡れる","君に合わせて歩いてみた"],"chorus":["遠くへ行くのもいいけれど","今は二人の速さでいい","濡れないことが目的じゃない","二人で歩く帰り道だ"],"v2":["水を避ければ腕が寄る","何でもない話が続いた"],"bridge":["雨が止めば離れる傘も","この歩幅なら残せるだろ"],"outro":"晴れ間が来ても急がない","hook":["A slower step beneath the rain","We let the street go past again"]},{"id":"jp-116","lang":"jp","theme":"そばにいる人への感謝","title":"名前のない手伝い","v1":["終わったあとに人は帰る","君は椅子をまだ運んでる"],"chorus":["拍手のあとの音を聴こう","目立たぬ足音忘れない","表に書かれぬ名前にも","今日を作った手があるんだ"],"v2":["手伝おうかと言いかけて","黙って隣の椅子を持った"],"bridge":["見ているだけの礼よりも","同じ重さを分けてみる"],"outro":"二脚の脚が揃って鳴る","hook":["A quiet hand behind the cheer","Can make the whole night happen here"]},{"id":"jp-117","lang":"jp","theme":"そばにいる人への感謝","title":"一番後ろの頷き","v1":["話す途中で言葉が飛んだ","後ろの君が頷いていた"],"chorus":["続きを知ってる顔じゃなく","聴いてる顔に助けられた","うまく話せる人よりも","話せる場所が欲しかった"],"v2":["うまく言えずに終わったあと","伝わったよと君が笑った"],"bridge":["全部を分かることよりも","聞こうとする目を信じたい"],"outro":"今度は俺が席へ座る","hook":["A listening face across the room","Can give a stumbling voice some room"]},{"id":"jp-118","lang":"jp","theme":"そばにいる人への感謝","title":"余った弁当","v1":["多く作っただけだと言って","包みを少し押してきた"],"chorus":["言わない言葉も受け取るよ","味の向こうに手間がある","余りだなんて言うけれど","俺の好みが入っていた"],"v2":["空の箱を洗って返す","美味しかったとだけ添えた"],"bridge":["大げさにすると照れるから","小さな礼を続けてゆこう"],"outro":"次も多めに作ってくれ","hook":["You say there's more than you can eat","I taste the care beneath the heat"]},{"id":"jp-119","lang":"jp","theme":"そばにいる人への感謝","title":"借りた静けさ","v1":["君の部屋では急がなくなる","時計の音まで丸く聞こえる"],"chorus":["話さないままいてもいい","そんな場所をくれてありがとう","言葉で埋めない優しさが","窓の光に溶けている"],"v2":["窓辺の光を二人で見て","何か言うのをやめてみた"],"bridge":["埋めなくたっていい空白","俺も誰かに渡したい"],"outro":"湯気の行方を眺めていた","hook":["A quiet room, a softer clock","Has room for words that need no knock"]},{"id":"jp-120","lang":"jp","theme":"寓話と幻想","title":"錆の王冠","v1":["玄関先に冠がある","誰かの名前が削ってあった"],"chorus":["借りた王にはならないよ","俺の重さで立っていたい","きれいな鎖で飾るより","汗をかく額のままでいい"],"v2":["被れば楽だと声がする","鏡の顔は俯いたまま"],"bridge":["選ばぬ誓いを脱ぎ捨てて","額の汗で道を選べ"],"outro":"冠は戸口に置いておく","hook":["No borrowed flame, no hollow throne","I take the weight that is my own"]},{"id":"jp-121","lang":"jp","theme":"寓話と幻想","title":"紙の海賊船","v1":["新聞紙の帆を立てた","昨日のニュースで海へ出る"],"chorus":["沈むと決めた大人たち","まだ濡れてない風を見ろ","小さな波にも舵がいる","紙の船にも行く先がある"],"v2":["水たまりには波がある","靴の先から嵐が来た"],"bridge":["小さな船の船長でも","行く方向は決められる"],"outro":"雨樋の先へ漕ぎ出そう","hook":["A paper sail, a shallow sea","Can hold a captain just like me"]},{"id":"jp-122","lang":"jp","theme":"寓話と幻想","title":"月を売る店","v1":["路地の奥には月が並ぶ","欠けたものほど高くなる"],"chorus":["足りないところを愛せるか","夜の商人が聞いてくる","足りないところを隠すより","そこから光を通してみろ"],"v2":["丸い月なら値がつかない","持ち帰るには重すぎると"],"bridge":["俺の欠けた話をしたら","店の灯りが少し揺れた"],"outro":"包まず月を手渡された","hook":["A missing piece can let light through","The broken moon can teach me too"]},{"id":"jp-123","lang":"jp","theme":"寓話と幻想","title":"時計を食べる鳥","v1":["屋根の上には妙な鳥","毎朝五分をついばんでいる"],"chorus":["取り返すより見ていたい","急がぬ空を飛ぶ姿","きちんと並んだ数字より","跳ねる羽根から目が離せない"],"v2":["時刻表から穴が開いて","人は初めて顔を上げた"],"bridge":["無くした時間の隙間には","時計にないこと入れてみろ"],"outro":"鳥は今日も五分遅れる","hook":["A stolen minute takes the sky","And leaves a little room to try"]},{"id":"jp-124","lang":"jp","theme":"寓話と幻想","title":"眠る信号機","v1":["誰も通らぬ交差点で","信号だけが夢を見てる"],"chorus":["赤も青にもならないで","今夜は星の色になれ","二つの色で分けるより","夜の色ごと眺めていたい"],"v2":["立ち止まったら風が渡る","道の名前を忘れてしまう"],"bridge":["行くか止まるかだけじゃない","ここにいるにも色がある"],"outro":"黄色い夢が瞬いてる","hook":["Beyond the red, beyond the green","A hundred shades are still unseen"]},{"id":"jp-125","lang":"jp","theme":"寓話と幻想","title":"声のない王国","v1":["声を預ける門がある","入れば皆が笑っている"],"chorus":["静かなだけの平和なら","俺の声ごと出てゆくよ","笑顔を守る門よりも","泣ける広場で会いたいんだ"],"v2":["返却口には列ができた","自分の声を探している"],"bridge":["大きい声も小さい声も","混ざる広場へ歩いてゆけ"],"outro":"門の外から歌が聞こえる","hook":["A perfect peace without a voice","Is not the place I call a choice"]},{"id":"jp-126","lang":"jp","theme":"寓話と幻想","title":"硝子の森","v1":["枝も葉もみな透き通る","風が吹くたび音が鳴る"],"chorus":["きれいなだけの森じゃない","傷つく光を聴いてくれ","光を独り占めする手より","開いた手から風を通せ"],"v2":["歩けば欠片が靴へ刺さる","座って景色を見直した"],"bridge":["触れたいことと壊すこと","同じ指でも違うはずだ"],"outro":"掌を開いて風を待つ","hook":["An open palm, a ringing tree","The wind can take what I can't keep"]},{"id":"jp-127","lang":"jp","theme":"寓話と幻想","title":"影の仕立屋","v1":["影が短いと相談した","店主は夕方を連れてきた"],"chorus":["大きく見せるその前に","どんな光に立つか決めろ","長い短いだけじゃなく","立ってる俺を見てみたい"],"v2":["長くなった影を引きずり","歩きにくさに苦笑いした"],"bridge":["自分より先へ伸びるもの","追うだけでは届かない"],"outro":"真上の昼も悪くない","hook":["A longer shade, a smaller stride","I want the light I stand inside"]},{"id":"jp-128","lang":"jp","theme":"寓話と幻想","title":"雨を集める街","v1":["屋根から雨を瓶へ詰め","皆が晴れを待っている"],"chorus":["泣いた空までしまうなら","晴れた明日には何が残る","閉じた蓋から漏れ出した","濡れた季節を分けてくれ"],"v2":["一つの瓶を開けたとき","遠い屋根の匂いがした"],"bridge":["乾いた心を飾るより","濡れた記憶を分けてみよう"],"outro":"窓の下へ雨を返した","hook":["A bottled storm, an opened lid","The smell of all the rain we hid"]},{"id":"jp-129","lang":"jp","theme":"寓話と幻想","title":"羽根のない郵便","v1":["空から手紙が降ってくる","差出人には雲の名前"],"chorus":["届かぬ言葉はないのだと","風の都合が嘘をつく","風が運ばぬ言葉なら","俺の両手で折ってゆこう"],"v2":["濡れた封筒乾かす間","知らない誰かを思っていた"],"bridge":["宛先ならば俺が書こう","雲に任せて待たないで"],"outro":"紙飛行機をひとつ折った","hook":["A folded word, a little flight","Can leave a cloud a line to write"]},{"id":"jp-130","lang":"jp","theme":"寓話と幻想","title":"逆さまの灯台","v1":["海の底へと灯りを向け","船には暗い灯台がある"],"chorus":["上だけ見ても見えないさ","沈んだ光も道になる","上から見えない道を照らす","誰の目線で無駄と決める"],"v2":["誰も褒めずに通り過ぎる","魚の群れが輪を描いた"],"bridge":["役に立つかを決める目も","時には底へ向けてみろ"],"outro":"水面が下から明るくなる","hook":["Below the waves, a hidden beam","Can find a road outside the scheme"]},{"id":"jp-131","lang":"jp","theme":"寓話と幻想","title":"夜明けを買う男","v1":["袋いっぱい夜を集め","朝の市場へ持ってゆく"],"chorus":["明るいだけの明日より","暗さを知った光をくれ","手に入れることばかり見て","開く空まで忘れていた"],"v2":["店は閉まって誰もいない","袋の口から鳥が飛んだ"],"bridge":["買わなくたって来るものを","手放すまでは待てなかった"],"outro":"空いた袋へ風が入る","hook":["I let the dark out of the sack","And saw the morning looking back"]},{"id":"jp-132","lang":"jp","theme":"喪失と再出発","title":"空いた釘","v1":["壁に一本釘が残る","外したものより目についてる"],"chorus":["何も掛けずに置いておこう","なくした形も部屋の一部","飾らない場所があってもいい","傷を隠さぬ壁のままで"],"v2":["別の絵ならあるけれど","今日はそちらへ手が伸びない"],"bridge":["急いで埋める空白より","慣れる時間を選びたい"],"outro":"窓の影だけ掛かっている","hook":["An empty nail, an honest wall","Can keep the shape I still recall"]},{"id":"jp-133","lang":"jp","theme":"喪失と再出発","title":"片方の手袋","v1":["片方だけを落とした冬","残りを捨てる気になれない"],"chorus":["揃わぬままでも温かい","残ったものまで手放さない","なくした方へ伸びる手を","残る温かさで包んでやれ"],"v2":["ポケットの中で丸めたら","両手を入れるには小さい"],"bridge":["代わりを探すその前に","役目を少し変えてみる"],"outro":"小さな袋に縫い直した","hook":["The other glove is somewhere new","I keep the warmth that made it through"]},{"id":"jp-134","lang":"jp","theme":"喪失と再出発","title":"引っ越しの余白","v1":["家具を出したら声が響く","広さを今さら知る部屋だ"],"chorus":["持てるものだけ持ってゆこう","残すものにも頭を下げて","持たずに行っても消えないもの","手ぶらの中にも残っている"],"v2":["棚の跡だけ日焼けしてない","暮らした形が白く残る"],"bridge":["全部連れては行けないが","ここで覚えた癖は行く"],"outro":"鍵を静かに置いてきた","hook":["An empty room can hold the trace","Of how a life once filled the space"]},{"id":"jp-135","lang":"jp","theme":"喪失と再出発","title":"失くした時計","v1":["いつもの手首が軽すぎる","何度も空へ目を落とした"],"chorus":["時間が消えたわけじゃない","測る道具を失くしただけ","針のない今日を歩いたら","空の動きに気づけたんだ"],"v2":["夕方の色で帰ってみる","知らない鳥の声を聴いた"],"bridge":["便利だったと惜しみつつ","不便な今日も歩けるんだ"],"outro":"手首に風が当たっている","hook":["The wrist is bare, the sky moves on","A different way to know the dawn"]},{"id":"jp-136","lang":"jp","theme":"喪失と再出発","title":"修理中の看板","v1":["閉めた店には紙が一枚","しばらく休むと書いてある"],"chorus":["終わりと休みは違うから","この戸口まで消さないで","閉じた扉のその奥で","まだ動く手を信じてる"],"v2":["遠回りして前を通る","灯りが一つ奥でついてた"],"bridge":["待つしかできぬ日があっても","できることまで無くなってない"],"outro":"紙の端へ石を置いた","hook":["A closed-up door, a working light","Can mean a pause and not goodnight"]},{"id":"jp-137","lang":"jp","theme":"喪失と再出発","title":"水にほどけた地図","v1":["雨で地図から線が消えた","右も左も色が混ざる"],"chorus":["決めた道だけ道じゃない","今見える角を曲がってみろ","消えた線にも礼を言い","見える景色で決めてゆく"],"v2":["迷って着いた小さな橋","知らない景色で靴が止まる"],"bridge":["元の予定は戻らないが","今日を戻す必要はない"],"outro":"濡れた紙を丁寧に畳む","hook":["A map runs out, a bridge appears","The road can move beyond the fears"]},{"id":"jp-138","lang":"jp","theme":"喪失と再出発","title":"折れた傘の使い道","v1":["骨が一本曲がった傘","捨てる場所まで迷っていた"],"chorus":["守れぬ形になったって","持った記憶は濡れはしない","壊れたままで呼ぶよりも","これからの名を探してやれ"],"v2":["布を外せば色がきれいだ","何か包めると広げてみる"],"bridge":["同じ役目に戻らなくても","続く形は探せるだろ"],"outro":"小さな鞄を縫い始める","hook":["A broken frame, a useful cloth","Can be the shape of something soft"]},{"id":"jp-139","lang":"jp","theme":"喪失と再出発","title":"返した合鍵","v1":["鍵を返して手が空いた","軽さを自由と呼べずにいる"],"chorus":["何も持たない掌で","今度は何を選ぼうか","軽くなったと笑えるまで","小さい歩幅で進んでゆく"],"v2":["いつもの角を曲がりかけ","違う道へと足を向けた"],"bridge":["忘れられない日があっても","同じ扉へ戻らなくていい"],"outro":"知らない店でお茶を頼む","hook":["An empty hand, another street","A smaller pace beneath my feet"]},{"id":"jp-140","lang":"jp","theme":"喪失と再出発","title":"花のない鉢","v1":["枯れた花だけ抜いたあと","土を捨てずに置いている"],"chorus":["何も咲かない季節にも","窓の光は来てくれる","咲いた姿を急かすより","見えない土をほぐしてゆく"],"v2":["種を買ったが蒔かないまま","まずは固い土をほぐした"],"bridge":["急いで咲かせることより","根を張る場所を作りたい"],"outro":"小さな袋を棚へ置く","hook":["A little soil, a waiting seed","Can take the time the roots will need"]},{"id":"jp-141","lang":"jp","theme":"喪失と再出発","title":"届かなかった荷物","v1":["宛先不明で戻ってきた","送る前より重く感じる"],"chorus":["渡せなかった気持ちまで","なかったことにはしないから","送れぬままの優しさも","ここに置く場所はあるはずだ"],"v2":["ほどいた紐を巻き直して","中の物だけ机へ出した"],"bridge":["別の誰かへ渡す前に","今の俺にも必要だった"],"outro":"箱を空けたまま座ってる","hook":["The parcel came back through the rain","I open what I couldn't explain"]},{"id":"jp-142","lang":"jp","theme":"喪失と再出発","title":"落書きの上書き","v1":["昔の文字を消しかけて","下の傷まで見えてきた"],"chorus":["消すより隣に書いてみる","昨日の俺もここにいていい","上書きだけが変化じゃない","並んだ文字にも明日はある"],"v2":["新しい文字は少し細い","前より上手くはないけれど"],"bridge":["変わることまで否定したら","続ける場所がなくなるだろ"],"outro":"二つの文字が風に乾く","hook":["Beside the old, another line","Two different hands can both be mine"]},{"id":"jp-143","lang":"jp","theme":"喪失と再出発","title":"朝の片づけ","v1":["散らかったまま寝てしまい","朝の光で目が覚めた"],"chorus":["全部いっぺんにできなくても","まずこの床へ足をつけよう","道がないなら片づけよう","俺の足で立てるところを"],"v2":["一つ拾えば次が見える","窓までの道が伸びてきた"],"bridge":["大きな決意は後でいい","小さな手から動かしてゆけ"],"outro":"珈琲を置く場所ができた","hook":["One little thing upon the shelf","Can make some room to find myself"]},{"id":"english-144","lang":"english","theme":"衝動","title":"The Wrong Name","v1":["They wrote my name the wrong way round","I almost let it make no sound"],"chorus":["Cross it out and let me sign","I want the letters to be mine","The smallest mark can make a stand","When it is made by my own hand"],"v2":["The clerk looked up and passed the pen","I wrote it slower than back then"],"bridge":["It wasn't just a spelling test","I needed me upon my chest"],"outro":"The ink took time enough to dry"},{"id":"english-145","lang":"english","theme":"衝動","title":"No Opening Bell","v1":["The market sleeps behind the steel","I hear the morning turning real"],"chorus":["No opening bell can start my day","I have a little light to make","A room can wait to let me in","The street is where I can begin"],"v2":["I set a table on the street","The waiting sun became my heat"],"bridge":["Permission never left a chair","For all the things already there"],"outro":"The shutter rises after me"},{"id":"english-146","lang":"english","theme":"恋の始まり","title":"Wrong Number","v1":["I dialed a friend and heard your voice","An accident without a choice"],"chorus":["The wrong number, the right hello","I nearly asked you not to go","The talk runs out, the weather stays","I find a reason in the rain"],"v2":["We talked about the falling rain","Then laughed at how I'd lost a name"],"bridge":["I cannot call this fate or art","Just one mistake I took to heart"],"outro":"I asked which name I ought to save"},{"id":"english-147","lang":"english","theme":"恋の始まり","title":"The Last Coin","v1":["I leave the smallest coin for last","To make your counting not too fast"],"chorus":["A little change can buy me time","To ask a question on my mind","I never wished for money more","Than wishing time inside this store"],"v2":["You say the coffee's getting cold","I ask what time the shutters fold"],"bridge":["There is no bargain for a smile","I only want to walk a while"],"outro":"You write the hour upon the bill"},{"id":"english-148","lang":"english","theme":"欲望と誘惑","title":"The House With No Clocks","v1":["The dealer's hands are very clean","The windows hide behind a screen"],"chorus":["One more round, the colors call","I want the turn that takes it all","A winning hand can feel so thin","When leaving isn't how I win"],"v2":["I win enough to leave the room","And put it back against the gloom"],"bridge":["The door was open all the time","The staying here was always mine"],"outro":"I count my steps instead of chips"},{"id":"english-149","lang":"english","theme":"欲望と誘惑","title":"Perfume on Paper","v1":["A stranger gave me folded air","A trace of someone wasn't there"],"chorus":["The paper knows a borrowed skin","I breathe a person into it","A faint suggestion on the fold","Can make the absent feel like gold"],"v2":["The scent grows faint against my palm","I close my hand to keep the calm"],"bridge":["I cannot make a touch from this","But wanting writes what doesn't exist"],"outro":"The paper opens in the street"},{"id":"english-150","lang":"english","theme":"嫉妬と執着","title":"The Songs You Skip","v1":["You skip the song I played for you","And hum a tune I never knew"],"chorus":["I cannot be your only sound","But hate the silence when I'm around","The tune moves on, I stand behind","And hear the smallness of my mind"],"v2":["I wait for one familiar line","And turn your pleasure into mine"],"bridge":["The music doesn't owe a debt","For every night I can't forget"],"outro":"I let the next song find its end"},{"id":"english-151","lang":"english","theme":"嫉妬と執着","title":"Your Good News","v1":["Your letter says you got the part","My answer stops behind my heart"],"chorus":["I want to cheer and mean it too","Without a little wound from you","A borrowed bitterness won't mend","The thing I want to tell a friend"],"v2":["I leave the envelope in view","My own has still not made it through"],"bridge":["Your winning didn't make me lose","I need a kinder pair of shoes"],"outro":"I write the word congratulations"},{"id":"english-152","lang":"english","theme":"楽しい日常","title":"The Terrible Photo","v1":["We blinked and moved and lost the light","The picture still came out all right"],"chorus":["Keep the terrible photograph","It knows exactly how we laughed","No perfect face can hold the place","Of laughter moving through a face"],"v2":["We tried again with perfect smiles","And looked like strangers all the while"],"bridge":["A crooked frame can hold the truth","Of people not arranging proof"],"outro":"The bad one gets the little frame"},{"id":"english-153","lang":"english","theme":"楽しい日常","title":"Kitchen Band","v1":["A wooden spoon can keep the time","A kettle sings a crooked line"],"chorus":["The kitchen band is out of tune","But everybody knows the groove","No grand debut, no curtain call","Just breakfast making sense of all"],"v2":["The toast arrived a little late","The spoons began to celebrate"],"bridge":["We need no ticket at the door","Just someone tapping on the floor"],"outro":"The kettle takes another bow"},{"id":"english-154","lang":"english","theme":"生活への違和感","title":"Everybody on Mute","v1":["The television mouths the news","I watch the faces lose their use"],"chorus":["Everybody's talking loud","I turn it down and hear the crowd","Behind the screen, beneath the light","The world is more than words tonight"],"v2":["The room grows quiet, not the street","A distant footstep finds a beat"],"bridge":["The switch won't make the trouble cease","But gives my own voice a release"],"outro":"I open up the window first"},{"id":"english-155","lang":"english","theme":"生活への違和感","title":"The Lift Stops Here","v1":["I press the button out of habit","And never see the floors around it"],"chorus":["The lift stops here, I take the stairs","I want to know what waits between","A single floor beneath the routine","Can hold a world I haven't seen"],"v2":["A landing smells of someone's meal","A door has shoes I know are real"],"bridge":["The numbers kept the world so neat","They hid the places under feet"],"outro":"I learn the building one floor down"},{"id":"english-156","lang":"english","theme":"自信と挑戦","title":"The Silent Piano","v1":["The pianist never came that day","They asked if I could sing that way"],"chorus":["No keys beneath me, still a song","Enough of me to carry on","An empty seat, a single breath","Can show the voice I've always kept"],"v2":["The first note felt too bare to keep","The second found its own small feet"],"bridge":["A missing part is not the end","Of everything I have to send"],"outro":"I thank the room with just my voice"},{"id":"english-157","lang":"english","theme":"自信と挑戦","title":"The Longest Minute","v1":["The stopwatch waits beside the track","I nearly put the whole thing back"],"chorus":["One minute longer than before","Is not a lot, but it is more","A private clock, a public tree","Can mark a change that's only me"],"v2":["The finish line was just a tree","I learned a different size of me"],"bridge":["No one was there to call my name","I knew the time and felt the change"],"outro":"I leave the watch beside my shoes"},{"id":"english-158","lang":"english","theme":"迷いと不安","title":"Hands Before the Song","v1":["My hands won't hold the glass quite still","The water trembles where I will"],"chorus":["These hands are mine before the song","They don't have to be so strong","The shaking doesn't mean I'm gone","It means a person carries on"],"v2":["I put the glass down on the floor","And let them shake a little more"],"bridge":["The room can have a person first","Before a voice that never hurts"],"outro":"I reach the microphone again"},{"id":"english-159","lang":"english","theme":"迷いと不安","title":"Two Versions","v1":["I wrote two futures on the sheet","Both had a roof and food to eat"],"chorus":["Two versions of the same small life","I cannot fold the page tonight","The roads can both be something real","And still not tell me how to feel"],"v2":["I tried to hear which sounded true","And found a fear inside the two"],"bridge":["A choice won't make the other bad","Or turn the doubt to something glad"],"outro":"I put the pencil down to sleep"},{"id":"english-160","lang":"english","theme":"記憶と郷愁","title":"The Forgotten Birthday","v1":["I nearly missed my birthday twice","A calendar gave me advice"],"chorus":["A paper date, a childhood cake","I hear the wish I used to make","No former wish can count the ways","I find a little joy these days"],"v2":["The candles once outnumbered plans","Now plans take up both my hands"],"bridge":["No party here, no grand review","I buy one cake and cut it through"],"outro":"The icing leaves a younger smile"},{"id":"english-161","lang":"english","theme":"記憶と郷愁","title":"Faces on the Beach","v1":["I found a photograph in sand","A family I had never known"],"chorus":["Somebody's summer on a shore","Deserves a place that isn't lost","A faded face, a stranger's day","Can make my own life less far away"],"v2":["I put it by the ticket stand","And thought of pictures in my home"],"bridge":["A stranger's moment made me see","The careless things I keep with me"],"outro":"I call back home before the train"},{"id":"english-162","lang":"english","theme":"そばにいる人への感謝","title":"The Door You Held","v1":["My hands were full of awkward bags","You kept the door from swinging back"],"chorus":["The little time you gave for free","Has carried something home with me","A second spent upon the hinge","Can let a little kindness in"],"v2":["I didn't know your name or street","I saw another pair of feet"],"bridge":["I hold the next door open wide","For someone on the other side"],"outro":"A stranger smiles and walks on through"},{"id":"english-163","lang":"english","theme":"そばにいる人への感謝","title":"An Extra Place","v1":["You set a plate without a speech","I thought the table out of reach"],"chorus":["A place for me before a word","Was more than anything I'd heard","No interview, no need to shine","An ordinary chair is mine"],"v2":["I brought no story worth the meal","You let the ordinary feel"],"bridge":["Like something we could share and keep","Without a reason running deep"],"outro":"I stay to help you clear the plates"},{"id":"english-164","lang":"english","theme":"寓話と幻想","title":"Ocean in the Drawer","v1":["The office drawer was full of sea","A little wave came asking me"],"chorus":["An ocean in a wooden square","Has found a person needing air","No map can fold this water tight","It keeps the desk awake at night"],"v2":["I put my hand below the foam","A paper boat was going home"],"bridge":["The desk was small, the tide was wide","I left the lock undone inside"],"outro":"A shell stays warm beside the pen"},{"id":"english-165","lang":"english","theme":"寓話と幻想","title":"The Keeper of Names","v1":["A keeper hangs our names on hooks","And never once opens the books"],"chorus":["A name can fit upon a nail","A person needs a longer tale","No tidy hook can hold it all","The stories spill beyond the wall"],"v2":["I took mine down and read it twice","It wasn't worth its printed price"],"bridge":["I gave it back with room to spare","For all the things not written there"],"outro":"The keeper finds a wider hook"},{"id":"english-166","lang":"english","theme":"喪失と再出発","title":"Friday Box","v1":["They gave me back a cardboard square","I packed the mug I'd left in there"],"chorus":["A job can end, a hand stays mine","I have to learn another line","No borrowed role upon the shelf","Can take the work of being myself"],"v2":["Outside the building, rain had stopped","I took the lid off what I'd boxed"],"bridge":["The cup was still a useful thing","Without the name the office brings"],"outro":"I carry it home by the handle"},{"id":"english-167","lang":"english","theme":"喪失と再出発","title":"Three Strings","v1":["Three strings remained upon the neck","I nearly put it back to rest"],"chorus":["A different tuning, fewer notes","Can give the missing room to float","Not whole again, not thrown away","A different voice can learn to play"],"v2":["I found a chord I'd never tried","It didn't fill what wasn't there"],"bridge":["The whole old song won't come back through","But something here can still be new"],"outro":"Three strings keep the afternoon"}];
